// Unwrap whatever arrived on the real-time path into one item per order.
// Accepts a Webhook item ({ body: <order> } or { body: { orders: [...] } } or { body: [...] })
// or a Shopify Trigger item (the order itself).
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let payload = j.body !== undefined ? j.body : j;
  if (payload && Array.isArray(payload.orders)) payload = payload.orders;
  const list = Array.isArray(payload) ? payload : [payload];
  for (const o of list) {
    if (o && typeof o === 'object') out.push({ json: o });
  }
}
if (out.length === 0) {
  throw new Error('Payload contained no order objects. Expected a single order, an array, or { orders: [...] }.');
}
return out;

// DEMO DATA - fully synthetic. No real customers, stores or phone numbers.
// Orders mimic the shape of a Shopify order payload so the same checks run in demo and live mode.
// Deterministic: a seeded generator, so every run returns the same 72 orders.
function makeRng(seed) {
  let s = seed >>> 0;
  return function () {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = makeRng(20260101);
const pick = (arr) => arr[Math.floor(rand() * arr.length)];
const pad = (n, w) => String(n).padStart(w, '0');

const stores = Array.from({ length: 12 }, (_, i) => 'Store A' + pad(i + 1, 2));
// Two stores get a higher defect rate so the report has something to rank.
const weakStores = { 'Store A03': 2.5, 'Store A09': 2.0 };

const validPhone = (n) => '+1 555 010 ' + pad(1000 + n, 4);
const badPhones = ['12345', '555-ABC-0101', '000000000', '+1 555', '++1 555 010 1000'];
const skus = ['SKU-1001', 'SKU-1002', 'SKU-1003', 'SKU-1004', 'SKU-1005', 'SKU-1006'];

const now = Date.now();
const out = [];
for (let i = 1; i <= 72; i++) {
  const isOnline = i % 4 === 0;
  const store = stores[i % 12];
  const boost = isOnline ? 1 : weakStores[store] || 1;
  const hit = (p) => rand() < p * boost;

  const price = 40 + Math.floor(rand() * 220);
  const qty = 1 + Math.floor(rand() * 3);
  const gross = price * qty;
  let discountPct = rand() < 0.5 ? 0 : Math.floor(rand() * 26);
  if (hit(0.06)) discountPct = 45 + Math.floor(rand() * 30); // suspicious
  const discount = Math.round(gross * discountPct) / 100;

  let phone = validPhone(i);
  if (hit(0.12)) phone = '';
  else if (hit(0.09)) phone = pick(badPhones);
  const email = hit(0.08) ? '' : 'customer' + pad(i, 3) + '@example.com';
  const missingAddress = isOnline && hit(0.1);

  out.push({
    json: {
      id: 900000 + i,
      name: '#' + (1000 + i),
      created_at: new Date(now - Math.floor(rand() * 24 * 3600 * 1000)).toISOString(),
      source_name: isOnline ? 'web' : 'pos',
      email: email,
      phone: phone,
      customer: { first_name: 'Customer', last_name: pad(i, 3) },
      total_line_items_price: gross.toFixed(2),
      total_discounts: discount.toFixed(2),
      shipping_address:
        isOnline && !missingAddress
          ? { address1: pad(i, 3) + ' Example Street', city: 'Sampletown', zip: '00000', country_code: 'US' }
          : null,
      shipping_lines: isOnline
        ? [{ code: 'standard', title: 'Standard shipping' }]
        : [{ code: 'pickup', title: 'In-store pickup' }],
      note_attributes: isOnline ? [] : [{ name: 'store', value: store }],
      line_items: [{ sku: pick(skus), quantity: qty, price: price.toFixed(2) }],
    },
  });
}
return out;

// Deterministic checks. No LLM involved. One issue code per rule so counts stay comparable over time.
const cfg = $('Config').first().json;
const runType = String(cfg.run_type);
const discountMax = Number(cfg.discountThresholdPct);
const minDigits = Number(cfg.minPhoneDigits);
const maxDigits = Number(cfg.maxPhoneDigits);
const warnRate = Number(cfg.digestWarnRatePct);

const text = (v) => (v === undefined || v === null ? '' : String(v).trim());
const round1 = (n) => Math.round(n * 10) / 10;

function storeOf(o) {
  const attrs = Array.isArray(o.note_attributes) ? o.note_attributes : [];
  const attr = attrs.find((a) => a && String(a.name).toLowerCase() === 'store');
  if (attr && text(attr.value)) return text(attr.value);
  if (text(o.store_name)) return text(o.store_name);
  const tag = text(o.tags).split(',').map((t) => t.trim()).find((t) => /^store:/i.test(t));
  if (tag) return tag.replace(/^store:\s*/i, '');
  if (o.location_id) return 'Location ' + o.location_id;
  return 'Online / unassigned';
}
function phoneOf(o) {
  const c = o.customer || {};
  const s = o.shipping_address || {};
  const b = o.billing_address || {};
  return text(o.phone) || text(c.phone) || text(s.phone) || text(b.phone);
}
function emailOf(o) {
  const c = o.customer || {};
  return text(o.email) || text(o.contact_email) || text(c.email);
}
function phoneProblem(raw) {
  const cleaned = raw.replace(/[\s().\-]/g, '');
  if (!/^\+?\d+$/.test(cleaned)) return 'contains characters other than digits, spaces, + ( ) . -';
  const digits = cleaned.replace(/^\+/, '');
  if (digits.length < minDigits || digits.length > maxDigits) {
    return digits.length + ' digits (allowed ' + minDigits + '-' + maxDigits + ')';
  }
  if (/^(\d)\1+$/.test(digits)) return 'one repeated digit';
  return null;
}
function needsShippingAddress(o) {
  if (text(o.source_name).toLowerCase() === 'pos') return false;
  const lines = Array.isArray(o.shipping_lines) ? o.shipping_lines : [];
  if (lines.some((l) => /pickup/i.test(text(l.code) + ' ' + text(l.title)))) return false;
  const attrs = Array.isArray(o.note_attributes) ? o.note_attributes : [];
  if (attrs.some((a) => String(a.name).toLowerCase() === 'delivery' && /pickup/i.test(text(a.value)))) return false;
  return true;
}
function discountPct(o) {
  const gross = Number(o.total_line_items_price !== undefined ? o.total_line_items_price : o.subtotal_price);
  const disc = Number(o.total_discounts);
  if (!(gross > 0) || !(disc >= 0)) return 0;
  return (disc / gross) * 100;
}

const stores = {};
const ensure = (s) =>
  stores[s] ||
  (stores[s] = { store: s, orders_checked: 0, orders_flagged: 0, with_missing_info: 0, counts: {}, flagged: [] });

const looksLikeOrder = (o) => o && (o.id !== undefined || o.name !== undefined || Array.isArray(o.line_items));
const incoming = $input.all().map((i) => i.json);
const orders = incoming.filter(looksLikeOrder);
if (incoming.length > 0 && orders.length === 0) {
  // A disabled live node passes its input through unchanged, which would end up here.
  throw new Error('No order data received. In live mode, enable the node "Shopify: Get Orders (LIVE)".');
}
for (const o of orders) {
  const st = ensure(storeOf(o));
  const issues = [];
  let missingInfo = false;

  if (!phoneOf(o)) {
    issues.push({ code: 'missing_phone', detail: 'no phone on order, customer or addresses' });
    missingInfo = true;
  } else {
    const problem = phoneProblem(phoneOf(o));
    if (problem) issues.push({ code: 'invalid_phone', detail: problem });
  }
  if (!emailOf(o)) {
    issues.push({ code: 'missing_email', detail: 'no email' });
    missingInfo = true;
  }
  if (needsShippingAddress(o)) {
    const a = o.shipping_address || {};
    const missing = ['address1', 'city'].filter((k) => !text(a[k]));
    if (!text(a.country) && !text(a.country_code)) missing.push('country');
    if (missing.length) {
      issues.push({ code: 'missing_shipping_address', detail: 'missing ' + missing.join(', ') });
      missingInfo = true;
    }
  }
  const pct = discountPct(o);
  if (pct > discountMax) {
    issues.push({ code: 'suspicious_discount', detail: round1(pct) + '% (limit ' + discountMax + '%)' });
  }

  st.orders_checked += 1;
  if (missingInfo) st.with_missing_info += 1;
  if (issues.length) {
    st.orders_flagged += 1;
    for (const x of issues) st.counts[x.code] = (st.counts[x.code] || 0) + 1;
    st.flagged.push({ order: text(o.name) || String(o.id), issues: issues });
  }
}

const all = Object.values(stores).sort((a, b) => a.store.localeCompare(b.store));
const out = [];

if (runType === 'order' || runType === 'demo') {
  for (const st of all) {
    if (st.orders_flagged === 0) continue;
    out.push({
      json: {
        kind: 'alert',
        store: st.store,
        orders_checked: st.orders_checked,
        orders_flagged: st.orders_flagged,
        issue_counts: st.counts,
        flagged_orders: st.flagged,
      },
    });
  }
}
if (runType === 'digest' || runType === 'demo') {
  const rows = all
    .map((st) => ({
      store: st.store,
      orders: st.orders_checked,
      with_missing_info: st.with_missing_info,
      missing_info_rate_pct: st.orders_checked ? round1((st.with_missing_info / st.orders_checked) * 100) : 0,
    }))
    .sort((a, b) => b.missing_info_rate_pct - a.missing_info_rate_pct || a.store.localeCompare(b.store));
  const totalOrders = rows.reduce((n, r) => n + r.orders, 0);
  const totalMissing = rows.reduce((n, r) => n + r.with_missing_info, 0);
  out.push({
    json: {
      kind: 'digest',
      orders: totalOrders,
      with_missing_info: totalMissing,
      missing_info_rate_pct: totalOrders ? round1((totalMissing / totalOrders) * 100) : 0,
      warn_rate_pct: warnRate,
      stores: rows,
    },
  });
}
if (out.length === 0) {
  out.push({ json: { kind: 'noop', orders_checked: orders.length, note: 'No issues found in ' + orders.length + ' order(s).' } });
}
return out;

// Turn each result item into a plain-text message plus routing fields (chat_id, send).
const cfg = $('Config').first().json;
let chatMap = {};
try {
  chatMap = JSON.parse(String(cfg.storeChatMap || '{}'));
} catch (e) {
  chatMap = {};
}
const defaultChat = String(cfg.telegramChatId || '').trim();

const LABELS = {
  missing_phone: 'missing phone',
  invalid_phone: 'invalid phone',
  missing_email: 'missing email',
  missing_shipping_address: 'missing shipping address',
  suspicious_discount: 'suspicious discount',
};
const MAX_LINES = 15;

return $input.all().map((item) => {
  const d = item.json;
  if (d.kind === 'alert') {
    const counts = Object.entries(d.issue_counts)
      .map(([k, v]) => (LABELS[k] || k) + ': ' + v)
      .join(', ');
    const lines = d.flagged_orders
      .slice(0, MAX_LINES)
      .map((f) => '- ' + f.order + ': ' + f.issues.map((x) => (LABELS[x.code] || x.code) + ' (' + x.detail + ')').join('; '));
    if (d.flagged_orders.length > MAX_LINES) lines.push('... and ' + (d.flagged_orders.length - MAX_LINES) + ' more');
    const chat = String(chatMap[d.store] || defaultChat);
    return {
      json: {
        kind: 'alert',
        store: d.store,
        chat_id: chat,
        send: chat !== '',
        reason_not_sent: chat ? '' : 'no chat id configured',
        message:
          'Order data quality - ' + d.store + '\n' +
          d.orders_flagged + ' of ' + d.orders_checked + ' orders need attention (' + counts + ')\n' +
          lines.join('\n'),
      },
    };
  }
  if (d.kind === 'digest') {
    const lines = d.stores.map(
      (r) =>
        (r.missing_info_rate_pct >= d.warn_rate_pct ? '! ' : '  ') +
        r.store + ': ' + r.missing_info_rate_pct + '% (' + r.with_missing_info + '/' + r.orders + ')'
    );
    return {
      json: {
        kind: 'digest',
        store: 'all',
        chat_id: defaultChat,
        send: defaultChat !== '',
        reason_not_sent: defaultChat ? '' : 'no chat id configured',
        message:
          'Daily digest - orders with missing phone, email or shipping address\n' +
          'Total: ' + d.missing_info_rate_pct + '% (' + d.with_missing_info + '/' + d.orders + ' orders). "!" marks stores at or above ' + d.warn_rate_pct + '%\n' +
          lines.join('\n'),
      },
    };
  }
  return { json: { kind: 'noop', store: '-', chat_id: '', send: false, reason_not_sent: 'nothing to report', message: d.note } };
});

// One compact JSON response for the webhook caller / the demo run.
const cfg = $('Config').first().json;
const msgs = $('Format Messages').all().map((i) => i.json);
return [
  {
    json: {
      mode: cfg.mode,
      run_type: cfg.run_type,
      messages_built: msgs.length,
      messages_sent_to_telegram: cfg.mode === 'live' ? msgs.filter((m) => m.send).length : 0,
      messages: msgs.map((m) => ({
        kind: m.kind,
        store: m.store,
        would_send: m.send,
        reason_not_sent: m.reason_not_sent,
        message: m.message,
      })),
    },
  },
];
